package ktanesolver.module.modded.regular.curseddoubleoh;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.*;
class CursedDoubleOhSolverTest{private final CursedDoubleOhSolver solver=new CursedDoubleOhSolver();
 @Test void findsLegalRouteWithoutRepeatedButtonsOrCells(){List<String>f=List.of("SMALL_UP","SMALL_RIGHT","LARGE_LEFT","LARGE_DOWN");CursedDoubleOhOutput out=solve(new CursedDoubleOhInput(60,f),new ModuleEntity());assertThat(out.presses().getLast()).isEqualTo("SUBMIT");assertThat(out.visitedNumbers().getLast()).isEqualTo("00");assertThat(out.visitedNumbers()).doesNotHaveDuplicates();for(int i=1;i<out.presses().size()-1;i++)assertThat(out.presses().get(i)).isNotEqualTo(out.presses().get(i-1));}
 @Test void handlesEveryDirectionChoiceAndPhysicalPermutation(){List<List<String>>families=List.of(List.of("SMALL_LEFT","SMALL_RIGHT"),List.of("SMALL_UP","SMALL_DOWN"),List.of("LARGE_LEFT","LARGE_RIGHT"),List.of("LARGE_UP","LARGE_DOWN"));for(int mask=0;mask<16;mask++){List<String>base=new ArrayList<>();for(int i=0;i<4;i++)base.add(families.get(i).get((mask>>i)&1));for(List<String>p:permutations(base))assertThat(CursedDoubleOhSolver.findPath(index(83),p)).isNotNull();}}
 @Test void persistsOnlySuccessfulAttemptSouvenirDigitAndRejectsBadWiring(){ModuleEntity m=new ModuleEntity();solve(new CursedDoubleOhInput(83,List.of("SMALL_UP","SMALL_RIGHT","LARGE_LEFT","LARGE_DOWN")),m);assertThat(m.getState()).containsEntry("cursedDoubleOhInitialFirstDigit","8");assertThat(result(new CursedDoubleOhInput(83,List.of("SMALL_LEFT","SMALL_RIGHT","LARGE_LEFT","LARGE_UP")),new ModuleEntity())).isInstanceOf(SolveFailure.class);}
 private CursedDoubleOhOutput solve(CursedDoubleOhInput i,ModuleEntity m){return((SolveSuccess<CursedDoubleOhOutput>)result(i,m)).output();}private Object result(CursedDoubleOhInput i,ModuleEntity m){return solver.solve(new RoundEntity(),new BombEntity(),m,i);}private static int index(int n){for(int i=0;i<CursedDoubleOhSolver.GRID.length;i++)if(CursedDoubleOhSolver.GRID[i]==n)return i;return-1;}private static List<List<String>>permutations(List<String>v){List<List<String>>r=new ArrayList<>();perm(v,0,r);return r;}private static void perm(List<String>v,int i,List<List<String>>r){if(i==v.size()){r.add(List.copyOf(v));return;}for(int j=i;j<v.size();j++){Collections.swap(v,i,j);perm(v,i+1,r);Collections.swap(v,i,j);}}
}
